scenario.irule:
when HTTP_REQUEST { set ::static_ctx [ADAPT::context_static request]; set ::request_ctx [ADAPT::context_create request_ctx]; ADAPT::select $::request_ctx /Common/request-ivs; ADAPT::enable $::request_ctx true; ADAPT::allow $::request_ctx http_v1.0 false; ADAPT::preview_size $::request_ctx 128; ADAPT::service_down_action $::request_ctx drop; ADAPT::timeout $::request_ctx 5000; log local0. "static=[ADAPT::context_name $::static_ctx] request=[ADAPT::context_name $::request_ctx] enabled=[ADAPT::enable $::request_ctx] allow=[ADAPT::allow $::request_ctx http_v1.0] preview=[ADAPT::preview_size $::request_ctx] action=[ADAPT::service_down_action $::request_ctx] timeout=[ADAPT::timeout $::request_ctx]" }
when ADAPT_REQUEST_HEADERS { log local0. "header-result=[ADAPT::result]" }
when ADAPT_REQUEST_RESULT { log local0. "current=[ADAPT::context_name [ADAPT::context_current]] result=[ADAPT::result]"; ADAPT::result bypass }
